export const STUDIO_ADMIN_HTML="<!doctype html><html lang=\"ro\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#061827\"><title>myPocketAI · Studio site-uri</title><style>\n:root{color-scheme:dark;--bg:#061827;--panel:#0b283a;--panel2:#12384c;--line:#35687e;--ink:#edf6f9;--muted:#a6c3d0;--accent:#67c5dc;--wine:#7b304a}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--ink)}\nbody{background:radial-gradient(ellipse at 20% -40%,#19506a,transparent 58%),#061827}\na{color:#8ce4f1}button,input,select,textarea{font:inherit}\nheader{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:12px;justify-content:space-between;padding:16px max(18px,calc((100% - 1060px)/2));background:#081b2bef;border-bottom:1px solid #3c6876}\nheader strong{font-size:23px;letter-spacing:-.04em}header small{display:block;font-size:11px;letter-spacing:.18em;color:var(--accent);text-transform:uppercase;font-weight:750}\nheader .identity{font-size:12px;color:var(--muted);text-align:right;max-width:42%;overflow-wrap:anywhere}\nmain{width:min(100% - 28px,1060px);margin:25px auto 120px;display:grid;gap:18px}\n.eyebrow{font-size:12px;color:var(--accent);letter-spacing:.17em;font-weight:800;text-transform:uppercase}\nh1{font:700 clamp(27px,5vw,40px)/1.12 Georgia,serif;margin:10px 0 15px}h2{font-size:22px;margin:6px 0 14px}h3{font-size:18px;margin:12px 0}\n.panel{padding:22px;background:#102e42;border:1px solid #3c7084;border-radius:19px;box-shadow:0 10px 35px #0002}\n.panel.darker{background:#0a2333}\n.subtle{font-size:13px;line-height:1.55;color:var(--muted)}\n.notice{border-left:4px solid #85b8d2;background:#0f3145;padding:12px 15px;border-radius:0 12px 12px 0;font-size:13px;line-height:1.5;color:#d4e9ef}\n.warning{border-color:#dcaa7a}\n.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}\n.grid.wide{grid-template-columns:repeat(3,minmax(0,1fr))}\n.field{display:flex;flex-direction:column;gap:7px;margin:0 0 13px}\n.field>span{font-size:13px;font-weight:750;color:#d5eaf3}\ninput,select,textarea{width:100%;min-width:0;padding:12px 13px;background:#0b2435;border:1px solid #58849a;color:#f1fcff;border-radius:11px;outline:none}\ninput:focus,select:focus,textarea:focus{border-color:#88e1ef;box-shadow:0 0 0 2px #70bdd02d}\ninput:disabled,textarea:disabled,select:disabled{opacity:.58}\ntextarea{min-height:90px;resize:vertical;line-height:1.45}\ninput[type=file]{border:0;padding:0}\nbutton{background:linear-gradient(#8e405b,#6a263f);border:1px solid #d09cb0;color:white;border-radius:11px;min-height:43px;padding:10px 16px;font-weight:750;cursor:pointer}\nbutton.secondary{background:linear-gradient(#1c5674,#0d3a55);border-color:#74b7cf}\nbutton.neutral{background:transparent;border-color:#5a8ca1}\nbutton:disabled{opacity:.5;cursor:not-allowed}\nbutton:focus-visible{outline:3px solid #9ee6f6}\n.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n.row.between{justify-content:space-between}\n.row>button{flex:0 1 auto}\n.site-card{display:flex;gap:13px;justify-content:space-between;align-items:center;background:#14374b;border:1px solid #4b778c;padding:16px;border-radius:14px}\n.site-card strong{display:block;font-size:17px}\n.site-card small{display:block;color:#a9cfdd;font-size:12px;margin-top:5px}\n.site-card button{white-space:nowrap}\n.photo-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin:15px 0}\n.photo{display:flex;flex-direction:column;gap:5px;padding:7px;border-radius:11px;background:#153b50}\n.photo img{display:block;width:100%;height:116px;object-fit:cover;border-radius:8px}\n.photo input{font-size:11px;padding:6px}\n.photo button{min-height:31px;padding:4px 7px;font-size:12px}\n.preview-frame{display:block;width:100%;height:540px;border:1px solid #6c97aa;border-radius:14px;background:white}\n.preview-box{margin-top:18px}\nhr{border:0;border-top:1px solid #3c708466;margin:20px 0}\n#notice{position:fixed;bottom:15px;left:50%;transform:translateX(-50%);width:min(650px,calc(100% - 26px));padding:13px 16px;background:#19435a;border:1px solid #7ab5c6;border-radius:12px;box-shadow:0 9px 30px #0006;display:none;z-index:100;line-height:1.4;font-size:14px}\n#notice.show{display:block}\n.top-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}\n.top-actions button{min-height:38px;font-size:12px}\n.mode-badge{font-size:12px;color:#b2edec;background:#145264;padding:6px 10px;border-radius:20px;display:inline-flex;align-items:center}\n#gallery button{flex:1}\ndetails{border:1px solid #49798a;border-radius:11px;padding:13px;margin-top:14px}\nsummary{cursor:pointer;font-weight:750}\nbody:has(#dialog[open]){overflow:hidden}\ndialog{width:min(730px,calc(100% - 20px));max-height:90vh;border:1px solid #75b7c8;border-radius:18px;background:#0b283a;color:white;padding:19px;overflow-y:auto}\ndialog::backdrop{background:#031018e8}\n#site-preview{max-width:1050px}\n.help{font-size:12px;color:#c0dfe8}\nfooter{padding:30px 15px;text-align:center;color:#799aac;font-size:12px}\n@media(max-width:650px){\n main{margin:12px auto 100px}.panel{padding:16px;border-radius:15px}\n .grid,.grid.wide{grid-template-columns:1fr}\n header{padding:12px 14px}header strong{font-size:19px}\n .row>button{flex:1 1 45%}\n .photo-list{grid-template-columns:repeat(2,minmax(0,1fr))}\n .photo img{height:92px}\n .site-card{align-items:flex-start}\n .site-card button{max-width:120px;white-space:normal}\n input,select,textarea{font-size:16px}\n .preview-frame{height:480px}\n}\n#photo-new-custom[hidden]{display:none!important}\\n</style></head><body><header><div><small>myPocketAI / Creator</small><strong>Site Studio</strong></div><span class=\"identity\" id=\"auth-info\">Portal independent</span></header><main id=\"main\"><section class=\"panel\">Se încarcă panoul...</section></main><div id=\"notice\" role=\"status\" aria-live=\"polite\"></div><dialog id=\"dialog\"><div class=\"row between\"><h2>Contract de mentenanță</h2><button id=\"dialog-close\" class=\"neutral\">Închide</button></div><pre id=\"dialog-content\" style=\"white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 system-ui\"></pre><button id=\"dialog-download\">Descarcă proiectul</button></dialog><footer>Site Studio · Conturi independente · Proiectele se publică numai după aprobarea administratorului</footer><script nonce=\"__STUDIO_NONCE__\">\n(()=>{'use strict';\nconst $=id=>document.getElementById(id);\nconst main=$('main'),authInfo=$('auth-info'),notice=$('notice'),adminHint=$('admin-hint');\nconst themes=[['heritage','Asimetric boutique'],['coastal','Panoramic imersiv'],['forest','Organic & natură'],\n ['urban','Split-screen studio'],['art','Mozaic creativ'],['minimal','Minimal luxury'],\n ['rustic','Poveste în etape'],['luxury','Editorial de revistă'],['soft','Carduri premium'],\n ['tech','Business & conversii'],['retro','Tipografie îndrăzneață'],['wellness','Galerie vizuală']];\nconst galleryPresets=__SITE_GALLERY_CATALOG__;\nconst hostingPlans=__SITE_HOSTING_CATALOG__;\nconst kinds=[['hotel','Pensiune / cazare'],['restaurant','Restaurant / cafenea / bar'],\n ['services','Servicii'],['salon','Salon'],['shop','Magazin'],['personal','Portofoliu'],['other','Alt domeniu']];\nlet user=null,list=[],active=null,photos=[],products=[],creating=false,dirty=false,inviteHash='',photoCanEdit=true;\nconst msg=text=>{notice.textContent=String(text);notice.classList.add('show');\n clearTimeout(msg.timeout);msg.timeout=setTimeout(()=>notice.classList.remove('show'),6500)};\nconst escape=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(path,method='GET',data=null,extra={}){\n const options={method,credentials:'same-origin',headers:{...extra}};\n if(data!==null){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data)}\n let response;try{response=await fetch(path,options)}catch{throw Error('Nu există conexiune cu Studio.')}\n const body=await response.json().catch(()=>({error:'invalid_response'}));\n if(!response.ok)throw Error(String(body.error||'HTTP '+response.status));\n return body;\n}\nfunction button(title,cb,cls='secondary'){\n const b=document.createElement('button');b.type='button';b.className=cls;\n b.textContent=title;b.onclick=cb;return b;\n}\nfunction setHeader(){\n authInfo.textContent=user?user.email+' · '+(user.plan==='premium'?'Premium activ':user.plan==='trial'?'Trial':'Trial expirat'):'Portal independent pentru clienți';\n}\nconst field=(label,id,kind='text',value='',help='')=>'<label class=\"field\"><span>'+escape(label)+'</span>'+\n (kind==='textarea'?'<textarea id=\"'+id+'\">'+escape(value)+'</textarea>':\n kind==='select'?'<select id=\"'+id+'\"></select>':\n '<input id=\"'+id+'\" type=\"'+kind+'\" value=\"'+escape(value)+'\" autocomplete=\"off\">')+\n (help?'<small class=\"help\">'+escape(help)+'</small>':'')+'</label>';\nfunction populate(id,values,selected){\n const select=$(id);if(!select)return;\n select.replaceChildren();\n values.forEach(([value,label])=>{const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)});\n if(selected!==undefined)select.value=selected;\n}\nfunction read(id){return $(id)?.value.trim()||''}\nfunction offerInviteFromHash(){\n const h=location.hash;\n const m=/^#invite=([a-f0-9]{32}\\.[a-f0-9]{64})$/.exec(h);\n if(m)inviteHash=m[1];\n}\nasync function acceptInvitation(){\n if(!inviteHash||!user)return;\n const m=/^([a-f0-9]{32})\\.([a-f0-9]{64})$/.exec(inviteHash);if(!m)return;\n try{\n  await api('/api/sites/'+m[1]+'/redeem','POST',{token:m[2],email:user.email});\n  inviteHash='';history.replaceState(null,'','/');msg('Invitația a fost acceptată. Site-ul apare acum în lista ta.');\n }catch(e){msg('Invitația nu a putut fi acceptată: '+e.message)}\n}\nfunction renderAuth(mode='login'){\n user=null;setHeader();\n const intro=mode==='setup'?'Configurarea inițială a administratorului':\n mode==='register'?'Creează contul proprietarului':'Conectare administrator';\n main.innerHTML='<section class=\"panel\"><span class=\"eyebrow\">Studio / cont securizat</span><h1>'+intro+'</h1>'+\n '<p class=\"subtle\">Acest panou funcționează separat de Pocket AI. Accesul clientului nu folosește parola creatorului.</p>'+\n (mode==='setup'?field('E-mailul administratorului','email','email')+field('Parolă de cel puțin 12 caractere','password','password')+\n field('Cheia inițială de configurare','bootstrap','password'):\n field('E-mail','email','email')+field('Parolă (minimum 12 caractere)','password','password'))+\n (mode==='register'?'<p class=\"notice\">Înregistrarea este permisă numai cu invitația de predare primită de la creator.</p>':'')+\n '<div class=\"row\" id=\"auth-controls\"></div>'+\n '<hr><p class=\"subtle\">Nu există plată online activă. Premium poate fi activat numai printr-un proces verificat, după integrarea facturării.</p></section>';\n const row=$('auth-controls');\n const submit=button(mode==='setup'?'Configurează contul':mode==='register'?'Creează cont':'Conectează-te',async()=>{\n  const email=read('email'),password=$('password').value;\n  submit.disabled=true;\n  try{\n   if(mode==='setup'){\n    await api('/api/setup','POST',{email,password},{'X-Studio-Setup':$('bootstrap').value});\n    msg('Contul administratorului a fost creat. Conectează-te.');\n    renderAuth();\n   }else if(mode==='register'){\n    await api('/api/register','POST',{email,password,invite:inviteHash});\n    msg('Contul proprietarului este creat. Conectează-te cu parola aleasă.');\n    renderAuth();\n   }else{\n    const r=await api('/api/login','POST',{email,password});user=r.user;setHeader();\n    await acceptInvitation();await dashboard();\n   }\n  }catch(e){msg(e.message)}finally{submit.disabled=false}\n },'primary');\n row.append(submit);\n row.append(button('Conectare',()=>renderAuth('login'),'neutral'));\n if(inviteHash)row.append(button('Cont nou din invitație',()=>renderAuth('register'),'secondary'));\n row.append(button('Prima configurare',()=>renderAuth('setup'),'neutral'));\n}\nasync function dashboard(){\n try{const r=await api('/api/sites');list=r.sites||[]}catch(e){msg(e.message);return renderAuth()}\n active=null;creating=false;setHeader();\n main.innerHTML='<section class=\"panel\"><span class=\"eyebrow\">Site Studio / proiecte</span><h1>Site-urile tale</h1>'+\n '<p class=\"subtle\">Construiește, editează, predă clientului și publică proiecte. Fiecare proprietar se autentifică separat.</p>'+\n '<div class=\"row\" id=\"dashboard-actions\"></div><input type=\"file\" id=\"import-project-file\" accept=\".json,.pocket-site.json,application/json\" hidden><div class=\"notice\" id=\"plan-note\"></div></section>'+\n '<section class=\"panel darker\"><h2>Proiectele existente</h2><div id=\"site-list\"></div></section>';\n const canCreate=Boolean(user?.canCreate);\n const btn=button('＋ Creează un site',()=>renderEditor(null),'primary');btn.disabled=!canCreate;\n $('dashboard-actions').append(btn);\n const importer=button('📂 Importă proiect Pocket AI',()=>$('import-project-file').click(),'secondary');\n importer.disabled=!canCreate;$('dashboard-actions').append(importer,button('Deconectare',signOut,'neutral'));\n $('import-project-file').onchange=async event=>{\n  const file=event.target.files?.[0];if(!file)return;\n  try{\n   if(file.size>3200000)throw Error('Fișierul proiectului este prea mare.');\n   const body=JSON.parse(await file.text());\n   if(body?.schema!=='mypocket-studio-project-v1'||!body.draft||typeof body.draft.name!=='string')\n    throw Error('Fișierul nu este un proiect Pocket AI editabil.');\n   if(body.draft.photos&&!Array.isArray(body.draft.photos))throw Error('Galeria proiectului nu este validă.');\n   renderEditor(null,{draft:body.draft,management:body.management});\n   msg('Proiect importat local. Verifică datele, contractul și fotografiile înainte de creare.');\n  }catch(e){msg('Import eșuat: '+e.message)}\n  finally{event.target.value=''}\n };\n $('plan-note').textContent=user?.plan==='trial'?\n  'Trial de 3 zile până la '+new Date(user.expiresAt).toLocaleString('ro-RO')+\n  '. Este permis un singur site creat în Trial. Site-urile deja predate continuă să poată fi administrate.'\n  :user?.plan==='premium'?'Premium verificat manual în acest mediu. Nu este conectată încă facturarea online.':\n  'Perioada Trial s-a încheiat. Poți administra site-urile existente, dar nu poți crea proiecte noi.';\n const panel=$('site-list');\n if(!list.length)panel.textContent='Nu există proiecte create.';\n list.forEach(s=>{\n  const item=document.createElement('div');item.className='site-card';\n  const text=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');\n  title.textContent=s.name||'Site';sub.textContent='Proiect · '+s.id.slice(0,8);\n  text.append(title,sub);item.append(text,button('Deschide',()=>openSite(s.id)));\n  panel.append(item);\n });\n}\nasync function signOut(){\n try{await api('/api/logout','POST',{})}catch{}\n user=null;active=null;renderAuth();\n}\nconst emptyDraft=()=>({\n name:'',description:'',kind:'hotel',styleId:'heritage',lang:'ro',\n contact:{email:'',phone:'',address:''},\n content:{ro:{headline:'',intro:'',about:'',services:[]},en:{headline:'',intro:'',about:'',services:[]}},\n rooms:[],amenities:[],photos:[],features:{contact:false,booking:false,shop:false},commerce:{currency:'GBP',slotCapacity:0,slotMinutes:60,automaticConfirmation:false,emailNotifications:false,products:[]}\n});\nconst emptyManagement=()=>({mode:'owner',client:'',creator:'',monthly:'',currency:'GBP',edits:'',turnaround:'',\n extraCost:'',notice:'',hosting:'owner',backups:'none'});\nasync function openSite(id){\n try{const r=await api('/api/sites/'+id);active=r.site;await renderEditor(active)}catch(e){msg(e.message)}\n}\nconst lines=(arr,type)=>Array.isArray(arr)?arr.map(x=>\n type==='service'?x.title+' | '+(x.detail||''):type==='room'?x.count+' | '+x.label:String(x)).join('\\n'):'';\nconst splitValues=value=>String(value||'').split(/\\n/g).map(x=>x.trim()).filter(Boolean);\nconst gather=()=>{\n const draft=active?.draft?structuredClone(active.draft):emptyDraft();\n draft.name=read('site-name');draft.kind=read('site-kind');draft.styleId=read('site-style');\n draft.lang=read('site-lang');draft.description=read('site-description');\n draft.contact={email:read('site-email'),phone:read('site-phone'),address:read('site-address')};\n draft.rooms=splitValues(read('site-rooms')).map(x=>{const v=x.split('|');return {count:Number((v.shift()||'').trim())||0,label:v.join('|').trim()}}).filter(x=>x.label);\n draft.amenities=splitValues(read('site-amenities'));\n draft.features={contact:$('feat-contact').checked,booking:$('feat-booking').checked,shop:$('feat-shop').checked,privacyUrl:read('feat-privacy-url')};\n draft.commerce={currency:read('site-currency'),slotCapacity:Number(read('site-capacity'))||0,\n  slotMinutes:Number(read('site-slot-minutes'))||60,automaticConfirmation:$('feat-auto-booking').checked,\n  emailNotifications:$('feat-email-notices').checked,products:products.map(p=>({...p}))};\n for(const lang of ['ro','en']){\n  draft.content[lang]={headline:read(lang+'-headline'),intro:read(lang+'-intro'),about:read(lang+'-about'),\n   services:splitValues(read(lang+'-services')).map(x=>{const v=x.split('|');return {title:(v.shift()||'').trim(),detail:v.join('|').trim()}}).filter(x=>x.title)};\n }\n draft.photos=photos.slice();\n return draft;\n};\nconst getManagement=()=>{\n const m=emptyManagement();m.mode=read('mgmt-mode');\n if(m.mode!=='owner'){\n  m.client=read('mgmt-client');m.creator=read('mgmt-creator');m.monthly=read('mgmt-monthly');\n  m.currency=read('mgmt-currency');m.edits=read('mgmt-edits');m.turnaround=read('mgmt-turnaround');\n  m.extraCost=read('mgmt-extra');m.notice=read('mgmt-notice');\n  m.hosting=read('mgmt-hosting');m.backups=read('mgmt-backups');\n }\n return m;\n};\nfunction modeFields(){\n const parent=$('mode-fields'),current=read('mgmt-mode');parent.hidden=current==='owner';\n $('mgmt-mode-help').textContent=current==='owner'?\n  'Proprietarul poate modifica și publica independent, după predarea accesului.':\n current==='managed'?'Clientul poate solicita modificări. Publică doar creatorul.':\n 'Clientul modifică informațiile și fotografiile; creatorul păstrează controlul asupra designului.';\n}\n\nfunction galleryOptions(){\n const kind=read('site-kind')||'hotel';\n const isBar=kind==='restaurant'&&/\\b(?:bar|pub|cocktail|lounge|berărie|berarie|tavern|club)\\b/i.test(read('site-description'));\n const isCafe=kind==='restaurant'&&!isBar&&/\\b(?:cafenea|coffee|café|cafe|ceainărie|ceainarie)\\b/i.test(read('site-description'));\n const catalog=galleryPresets[isBar?'bar':isCafe?'cafe':kind]||galleryPresets.other;\n const values=[\n  {key:'cover',title:kind==='hotel'?'Exteriorul pensiunii (principală)':'Fotografia principală',group:'exterior',label:'',en:''},\n  {key:'other',title:'Alte fotografii',group:'other',label:'',en:''}\n ];\n if(kind==='hotel'){\n  for(const room of splitValues(read('site-rooms')).map(x=>x.split('|').slice(1).join('|').trim()).filter(Boolean))\n   values.push({key:'room:'+room,title:'Cameră: '+room,group:'room',label:room,en:room});\n }\n for(const [id,ro,en] of catalog)values.push({key:'category:'+id,title:ro,group:'category',label:ro,en});\n values.push({key:'custom',title:'＋ Categorie proprie…',group:'category',label:'',en:''});\n return values;\n}\nfunction photoSelection(photo,options){\n if(photo.group==='exterior')return 'cover';\n if(photo.group==='other'||!photo.group)return 'other';\n const label=photo.categoryLabel||photo.roomLabel||'';\n const match=options.find(o=>o.key!=='custom'&&o.group===photo.group&&o.label===label);\n return match?match.key:'custom';\n}\nfunction photoTarget(label,selection,customValue=''){\n const option=galleryOptions().find(x=>x.key===selection);\n if(!option||option.key==='custom'){\n  const own=customValue.trim().slice(0,100);\n  if(own.length<2)throw Error('Introdu numele categoriei fotografice.');\n  return {group:'category',roomLabel:'',categoryLabel:own,categoryEn:own};\n }\n if(option.group==='room')return {group:'room',roomLabel:option.label,categoryLabel:option.label,categoryEn:option.en||option.label};\n if(option.group==='category')return {group:'category',roomLabel:'',categoryLabel:option.label,categoryEn:option.en||option.label};\n return {group:option.group,roomLabel:'',categoryLabel:'',categoryEn:''};\n}\nfunction fillNewPhotoTarget(){\n const selector=$('photo-new-target'),custom=$('photo-new-custom');if(!selector||!custom)return;\n const existing=selector.value;\n selector.replaceChildren();\n for(const option of galleryOptions()){\n  const item=document.createElement('option');item.value=option.key;item.textContent=option.title;selector.append(item);\n }\n selector.value=Array.from(selector.options).some(x=>x.value===existing)?existing:(photos.length?'other':'cover');\n const update=()=>{custom.hidden=selector.value!=='custom'};\n selector.onchange=update;update();\n}\nfunction renderPhotos(){\n const p=$('photos');if(!p)return;p.replaceChildren();\n const options=galleryOptions();\n photos.forEach((item,index)=>{\n  const card=document.createElement('div');card.className='photo';\n  const image=document.createElement('img');image.src=item.data;image.alt=item.caption||'Fotografie '+(index+1);\n  const caption=document.createElement('input');caption.value=item.caption||'';\n  caption.placeholder='Descriere fotografie';caption.disabled=!photoCanEdit;\n  caption.onchange=()=>{item.caption=caption.value.slice(0,130);dirty=true};\n  const category=document.createElement('select');category.disabled=!photoCanEdit;\n  for(const opt of options){\n   const element=document.createElement('option');element.value=opt.key;element.textContent=opt.title;category.append(element);\n  }\n  category.value=photoSelection(item,options);\n  const own=document.createElement('input');own.type='text';own.maxLength=100;\n  own.placeholder='Scrie numele categoriei';own.disabled=!photoCanEdit;\n  own.value=category.value==='custom'?(item.categoryLabel||item.roomLabel||''):'';\n  own.hidden=category.value!=='custom';\n  category.onchange=()=>{\n   own.hidden=category.value!=='custom';\n   if(category.value==='custom'){\n    if(!own.value)own.value=item.categoryLabel||item.roomLabel||'';\n    own.focus();\n   }else{\n    const info=photoTarget('',category.value);\n    if(info.group==='exterior')photos.forEach((p,n)=>{if(n!==index&&p.group==='exterior')p.group='other'});\n    Object.assign(item,info);dirty=true;renderPhotos();\n   }\n  };\n  own.onchange=()=>{\n   try{Object.assign(item,photoTarget('', 'custom',own.value));dirty=true;renderPhotos()}\n   catch(err){msg(err.message)}\n  };\n  const remove=button('Șterge fotografia',()=>{photos.splice(index,1);dirty=true;renderPhotos();fillNewPhotoTarget()},'neutral');\n  remove.disabled=!photoCanEdit;\n  card.append(image,caption,category,own,remove);p.append(card);\n });\n}\nasync function addPhoto(file){\n if(!file||!/^image\\/(jpeg|png|webp)$/.test(file.type)||file.size>8e6)\n  throw Error('Alege o fotografie JPG/PNG/WebP de maximum 8 MB.');\n if(photos.length>=40)throw Error('Maximum 40 fotografii în galeria site-ului.');\n const target=photoTarget('',$('photo-new-target')?.value||'other',$('photo-new-custom')?.value||'');\n const url=URL.createObjectURL(file),img=new Image();img.src=url;\n try{await img.decode()}finally{URL.revokeObjectURL(url)}\n const canvas=document.createElement('canvas');\n const scale=Math.min(1,820/Math.max(img.width,img.height));\n canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));\n canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);\n let data='';\n for(const quality of [.72,.58,.44,.30,.20]){\n  data=canvas.toDataURL('image/webp',quality);if(data.length<=105000)break;\n }\n if(data.length>105000)throw Error('Fotografia este prea mare după comprimare.');\n if(photos.reduce((n,item)=>n+item.data.length,0)+data.length>3000000)\n  throw Error('Galeria a atins limita de spațiu. Redu dimensiunea fotografiilor.');\n if(target.group==='exterior')for(const p of photos)if(p.group==='exterior')p.group='other';\n photos.push({data,caption:target.categoryLabel||'Fotografie furnizată de proprietar',...target});\n dirty=true;renderPhotos();fillNewPhotoTarget();\n}\nfunction renderHostingOptions(){\n const list=$('hosting-options'),mode=read('hosting-mode');\n if(!list)return;\n list.replaceChildren();\n $('hosting-notice').textContent=mode==='dynamic'?\n  'Atenție: HTML exportat nu implementează rezervări sau mesagerie. Un backend complet, autentificare, date și stocare imagini trebuie instalate și testate separat.':\n  'Pentru un site static sunt suficiente fișierele HTML și resursele sale. Administrarea live necesită un backend separat.';\n for(const plan of hostingPlans.filter(p=>p.mode===mode)){\n  const d=document.createElement('details');d.className='panel';\n  const summary=document.createElement('summary');summary.textContent=plan.title+(plan.best?' — recomandare de pornire':'');\n  const note=document.createElement('p');note.className='subtle';note.textContent=plan.ro;\n  const ol=document.createElement('ol');\n  for(const step of plan.stepsRo){const li=document.createElement('li');li.textContent=step;ol.append(li)}\n  const a=document.createElement('a');a.href=plan.doc;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Instrucțiunile oficiale ale furnizorului';\n  d.append(summary,note,ol,a);list.append(d);\n }\n}\nfunction downloadHostingInstructions(){\n const mode=read('hosting-mode'),rows=[\n  'GHID DE GĂZDUIRE EVA', 'Site: '+read('site-name'),\n  'Tip: '+(mode==='dynamic'?'Site interactiv':'Site static'),'',\n  'Clientul deține domeniul și contul de găzduire. Prețurile și limitele se verifică la furnizor.',\n  'Exportul HTML nu este un backend. Site-urile cu rezervări, mesagerie și conturi au nevoie de backend complet și testat.',''];\n for(const plan of hostingPlans.filter(p=>p.mode===mode)){\n  rows.push(plan.title,plan.ro,plan.doc);\n  plan.stepsRo.forEach((step,i)=>rows.push((i+1)+'. '+step));\n  rows.push('');\n }\n rows.push('La final verifică: domeniu, HTTPS, mobil, fotografii, conținut, permisiuni, backup, facturare și protecția datelor.');\n downloadText('eva-ghid-gazduire.txt',rows.join('\\n'));\n}\n\nasync function refreshVisitorInbox(){\n if(!active?.id||!$('visitor-inbox-content'))return;\n const panel=$('visitor-inbox-content');\n panel.textContent='Se încarcă mesajele și solicitările…';\n try{\n  const data=await api('/api/sites/'+active.id+'/inbox');\n  panel.replaceChildren();\n  if(!data.items?.length){panel.textContent='Nu sunt mesaje sau solicitări noi.';return}\n  for(const item of data.items){\n   const box=document.createElement('article');box.className='panel';\n   const head=document.createElement('h3');\n   head.textContent=(item.type==='booking'?'📅 Rezervare':item.type==='order'?'🛍 Comandă':'✉ Mesaj')+' · '+item.name+' · '+new Date(item.at).toLocaleString('ro-RO');\n   const info=document.createElement('p');info.className='subtle';\n   const booking=item.type==='booking'?\n    item.bookingType==='stay'?['Camera: '+(item.roomLabel||''),'Sosire: '+(item.start||''),'Plecare: '+(item.end||''),'Oaspeți: '+(item.partySize||'')].join(' · '):\n    ['Data: '+(item.date||''),'Ora: '+(item.time||''),'Persoane: '+(item.partySize||'')].join(' · '):'';\n   const money=item.type==='order'?' · '+item.productTitle+' × '+item.quantity+\n   ' · '+((item.totalMinor||0)/100).toFixed(2)+' '+(item.currency||'')+\n   ' · Plată: '+(item.paymentStatus||'neachitată'):'';\n   info.textContent='Stare: '+(item.status||'new')+' · '+(item.email||'')+money+\n    (item.phone?' · '+item.phone:'')+(booking?' · '+booking:'');\n   const message=document.createElement('p');message.textContent=item.message||'(fără detalii suplimentare)';\n   const actions=document.createElement('div');actions.className='row';\n   const email=document.createElement('a');email.href='mailto:'+encodeURIComponent(item.email||'');\n   email.textContent='✉ Răspunde prin e-mail';email.rel='noopener';\n   actions.append(email);\n   for(const [state,label] of [['contacted','Marchează contactat'],\n    ...(item.type==='booking'?[['confirmed','Confirmă rezervarea']]:[]),\n    ...(item.type==='order'?[['confirmed','Confirmă comanda'],['fulfilled','Marchează livrat']]:[]),\n    ['closed','Închide'],['declined','Refuză solicitarea']]){\n    actions.append(button(label,async()=>{\n     try{await api('/api/sites/'+active.id+'/inbox/'+item.id+'/status','POST',{status:state});await refreshVisitorInbox()}\n     catch(e){msg(e.message)}\n    },'secondary'));\n   }\n   actions.append(button('Șterge datele',async()=>{\n    if(!confirm('Ștergi definitiv această solicitare și datele vizitatorului din inbox?'))return;\n    try{await api('/api/sites/'+active.id+'/inbox/'+item.id,'DELETE');await refreshVisitorInbox()}\n    catch(e){msg(e.message)}\n   },'neutral'));\n   box.append(head,info,message,actions);panel.append(box);\n  }\n }catch(e){panel.textContent='Mesageria nu poate fi încărcată: '+e.message}\n}\nfunction renderCatalog(){\n const area=$('catalog-items');if(!area)return;area.replaceChildren();\n for(const [i,p] of products.entries()){\n  const box=document.createElement('section');box.className='site-card';\n  const fields=document.createElement('div');fields.style.flex='1';fields.style.minWidth='0';\n  const make=(label,value,type='text')=>{\n   const l=document.createElement('label');l.className='field';\n   const title=document.createElement('span');title.textContent=label;\n   const el=document.createElement('input');el.type=type;el.value=value;\n   if(type==='number'){el.min='0';el.step=label.includes('Preț')?'0.01':'1'}\n   l.append(title,el);fields.append(l);el.disabled=!photoCanEdit;return el;\n  };\n  const title=make('Produs',p.title),price=make('Preț unitate',(p.priceMinor/100).toFixed(2),'number');\n  const stock=make('Stoc disponibil',p.inventory,'number');\n  title.onchange=()=>{p.title=title.value.trim().slice(0,95);dirty=true};\n  price.onchange=()=>{p.priceMinor=Math.max(0,Math.round(Number(price.value||0)*100));dirty=true};\n  stock.onchange=()=>{p.inventory=Math.max(0,Math.floor(Number(stock.value||0)));dirty=true};\n  const remove=button('Șterge produsul',()=>{products.splice(i,1);dirty=true;renderCatalog()},'neutral');\n  remove.disabled=!photoCanEdit;\n  box.append(fields,remove);area.append(box);\n }\n if(!products.length)area.textContent='Niciun produs adăugat.';\n}\nfunction managementBlock(management,locked){\n const m=management||emptyManagement();\n return '<details'+(creating?' open':'')+'><summary>Administrare și contract de mentenanță</summary>'+\n field('Cine administrează site-ul?','mgmt-mode','select')+\n '<p class=\"subtle\" id=\"mgmt-mode-help\"></p><div id=\"mode-fields\">'+\n '<div class=\"grid\">'+field('Client / firmă','mgmt-client','text',m.client)+field('Prestator','mgmt-creator','text',m.creator)+'</div>'+\n '<div class=\"grid\">'+field('Tarif lunar','mgmt-monthly','text',m.monthly)+field('Moneda','mgmt-currency','select')+\n field('Modificări incluse lunar','mgmt-edits','text',m.edits)+field('Timp pentru modificări (zile lucrătoare)','mgmt-turnaround','text',m.turnaround)+\n field('Preț per modificare în plus','mgmt-extra','text',m.extraCost??m.extras)+field('Preaviz (zile)','mgmt-notice','text',m.notice)+'</div>'+\n field('Cine plătește domeniul și găzduirea?','mgmt-hosting','select')+\n field('Copii de siguranță','mgmt-backups','select')+\n '<button type=\"button\" id=\"contract-preview\" class=\"secondary\">📄 Vezi și exportă contractul</button>'+\n '</div><p class=\"help\">După crearea site-ului, modul de administrare rămâne stabil până la predare sau încheierea mentenanței.</p></details>';\n}\nfunction contractText(m,name){\n return 'PROPUNERE DE CONTRACT DE MENTENANȚĂ WEB\\n\\n'+\n 'Proiect: '+name+'\\nClient: '+m.client+'\\nPrestator: '+m.creator+'\\n\\n'+\n '1. DREPTURI. '+(m.mode==='managed'?'Prestatorul efectuează și publică modificări la cererea clientului.':\n  'Clientul poate modifica textele, fotografiile și prețurile; prestatorul gestionează designul și structura.')+'\\n'+\n '2. INCLUS. '+m.edits+' solicitări de modificare de conținut lunar. Termen maxim: '+m.turnaround+\n ' zile lucrătoare de la primirea materialelor și aprobărilor.\\n'+\n '3. EXCLUS. Redesign complet, pagini noi, integrări, publicitate, licențe, găzduire și domeniu, dacă nu sunt convenite separat.\\n'+\n '4. COST. '+m.monthly+' '+m.currency+'/lună. Modificări suplimentare doar după aprobarea unui preț de '+\n m.extraCost+' '+m.currency+'/solicitare. TVA și facturarea se clarifică între părți.\\n'+\n '5. GĂZDUIRE. '+(m.hosting==='owner'?'Proprietarul plătește direct domeniul și găzduirea.':\n 'Prestatorul gestionează găzduirea în baza unui acord separat.')+'\\n'+\n '6. BACKUP. '+({none:'Nu este inclus.',weekly:'O copie săptămânală.',monthly:'O copie lunară.'}[m.backups]||'Nespecificat')+'\\n'+\n '7. CONȚINUT. Clientul confirmă exactitatea informațiilor și drepturile asupra fotografiilor.\\n'+\n '8. ÎNCETARE. Preaviz '+m.notice+' zile. Datele și materialele clientului trebuie predate în format exportabil.'+\n ' Accesul creatorului se revocă atunci când este permis de condițiile convenite.\\n'+\n '9. ACEASTA ESTE O PROPUNERE, NU UN CONTRACT SEMNAT AUTOMAT. Revizuire juridică recomandată.\\n\\n'+\n 'Data: __________ Client: __________ Prestator: __________';\n}\nfunction downloadText(name,text){\n const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob);\n const a=document.createElement('a');a.href=url;a.download=name;a.click();\n setTimeout(()=>URL.revokeObjectURL(url),20000);\n}\nfunction setInput(id,value){if($(id))$(id).value=value??''}\nasync function renderEditor(site,prefill=null){\n creating=!site;active=site||null;\n const draft=site?.draft||prefill?.draft||emptyDraft(),management=site?.management||prefill?.management||emptyManagement();\n photos=structuredClone(draft.photos||[]);products=structuredClone(draft.commerce?.products||[]);dirty=false;\n const role=site?.role||'creator';\n const editable=creating||role==='creator'||(role==='owner'&&management.mode!=='managed');photoCanEdit=editable;\n const designEditable=creating||role==='creator'||(role==='owner'&&management.mode==='owner');\n const managedOnly=!creating&&!editable;\n main.innerHTML='<section class=\"panel\"><div class=\"row between\">'+\n '<div><span class=\"eyebrow\">Site Studio / '+(creating?'nou':'editor')+'</span><h1>'+\n (creating?'Site nou':'Administrare site')+'</h1></div><div class=\"top-actions\" id=\"editor-top\"></div></div>'+\n '<div class=\"notice\">'+(creating?'Poți pregăti site-ul fără niciun apel AI.':'Salvează modificările și verifică previzualizarea înainte de publicare.')+\n '</div></section>'+\n '<section class=\"panel\"><h2>Identitate și prezentare</h2><div class=\"grid\">'+\n field('Numele afacerii','site-name','text',draft.name)+field('Domeniu','site-kind','select')+\n field('Prezentare vizuală','site-style','select')+field('Limba','site-lang','select')+'</div>'+\n field('Descrierea completă a afacerii (în română)','site-description','textarea',draft.description)+\n '<p class=\"help\">Eva poate redacta automat conținut în română și engleză când motorul AI este activ. Datele introduse sunt păstrate numai în proiect.</p></section>'+\n '<section class=\"panel\"><h2>Texte și servicii</h2><div class=\"grid\">'+\n '<div>'+field('Titlu principal RO','ro-headline','text',draft.content?.ro?.headline)+\n field('Scurtă prezentare RO','ro-intro','textarea',draft.content?.ro?.intro)+\n field('Despre noi RO','ro-about','textarea',draft.content?.ro?.about)+\n field('Servicii RO: titlu | detalii, câte una pe rând','ro-services','textarea',lines(draft.content?.ro?.services,'service'))+'</div>'+\n '<div>'+field('Main title EN','en-headline','text',draft.content?.en?.headline)+\n field('Short introduction EN','en-intro','textarea',draft.content?.en?.intro)+\n field('About us EN','en-about','textarea',draft.content?.en?.about)+\n field('Services EN: title | details','en-services','textarea',lines(draft.content?.en?.services,'service'))+'</div></div>'+\n '<div class=\"row\" id=\"ai-copy-actions\"></div></section>'+\n '<section class=\"panel\"><h2>Camere, facilități și contact</h2><div class=\"grid\">'+\n field('Camere: cantitate | tip, pe rând','site-rooms','textarea',lines(draft.rooms,'room'))+\n field('Facilități: câte una pe rând','site-amenities','textarea',lines(draft.amenities))+\n field('E-mail de contact','site-email','email',draft.contact?.email)+\n field('Telefon','site-phone','text',draft.contact?.phone)+\n field('Adresă','site-address','text',draft.contact?.address)+'</div></section>'+\n '<section class=\"panel\"><h2>Funcții pentru vizitatori (backend)</h2>'+\n '<p class=\"subtle\">Activează numai funcțiile necesare. Mesajele și rezervările sunt solicitări, nu confirmări automate. Funcționează doar dacă site-ul și backendul sunt publicate împreună.</p>'+\n '<div class=\"grid\"><label class=\"field\"><span><input type=\"checkbox\" id=\"feat-contact\"> Mesagerie — formular de contact și inbox privat</span></label>'+\n '<label class=\"field\"><span><input type=\"checkbox\" id=\"feat-booking\"> Calendar și rezervări / programări</span></label>'+\n '<label class=\"field\"><span><input type=\"checkbox\" id=\"feat-shop\"> Produse, comenzi și plăți opționale</span></label>'+\n '<label class=\"field\"><span><input type=\"checkbox\" id=\"feat-auto-booking\"> Confirmă automat numai dacă există capacitate disponibilă</span></label>'+\n '<label class=\"field\"><span><input type=\"checkbox\" id=\"feat-email-notices\"> Notificări e-mail, doar dacă furnizorul este configurat</span></label></div>'+\n '<div class=\"grid\">'+field('Capacitate simultană mese / programări','site-capacity','number',draft.commerce?.slotCapacity??0)+\n field('Durata unui interval (minute)','site-slot-minutes','select')+\n field('Monedă produse','site-currency','select')+'</div>'+\n '<details><summary>🛍 Catalog de produse și stocuri</summary>'+\n '<p class=\"subtle\">Proprietarul introduce prețurile și stocurile reale; Eva nu le inventează. Plata online este disponibilă numai după conectarea contului Stripe al clientului.</p>'+\n '<div class=\"row\" id=\"catalog-actions\"></div><div id=\"catalog-items\"></div></details>'+\n field('Adresa HTTPS a politicii de confidențialitate (obligatorie la publicare cu formulare)','feat-privacy-url','text',draft.features?.privacyUrl||'')+\n '<p class=\"subtle\">Înainte de activare verifică politica de confidențialitate, datele de contact, capacitatea și procedura de răspuns. Fără link valid HTTPS, publicarea cu mesaje/rezervări este blocată.</p></section>'+\n '<section class=\"panel\"><h2>Galerie de fotografii</h2><p class=\"subtle\">Poze reale ale afacerii. Fotografia principală este separată de galerie. Alege tipul fotografiei din categoriile potrivite afacerii sau creează una nouă. Poți adăuga fotografii ulterior, în limita spațiului disponibil (acum 40 imagini comprimate). Vizitatorii le văd numai după publicare.</p>'+\n '<div id=\"photos\" class=\"photo-list\"></div>'+\n '<label class=\"field\"><span>În ce categorie adăugăm următoarea fotografie?</span><select id=\"photo-new-target\"></select></label>'+ \n '<label class=\"field\" id=\"photo-custom-label\"><span>Categorie proprie</span><input id=\"photo-new-custom\" type=\"text\" maxlength=\"100\" placeholder=\"Ex.: Deserturi, Tunsori, Grădină\" hidden></label>'+ \n '<div class=\"row\" id=\"photo-actions\"></div>'+\n '<input type=\"file\" id=\"add-photo-input\" accept=\"image/png,image/jpeg,image/webp\" hidden></section>'+\n (site?'<section class=\"panel\"><details id=\"client-inbox\" open><summary>📨 Mesaje și solicitări de rezervare</summary>'+\n '<p class=\"subtle\">Acest panou este privat. Nu trimite automat răspunsuri și nu confirmă automat rezervări. Folosește contactul clientului pentru răspuns.</p>'+\n '<div class=\"row\" id=\"visitor-inbox-actions\"></div><div id=\"visitor-inbox-content\"></div></details></section>':'')+\n '<section class=\"panel\" id=\"administration\">'+managementBlock(management,!creating)+'</section>'+\n '<section class=\"panel\"><h2>Salvare și publicare</h2><div class=\"row\" id=\"editor-actions\"></div>'+\n (site?'<div class=\"preview-box\"><iframe sandbox=\"\" class=\"preview-frame\" id=\"preview\" title=\"Previzualizare site\"></iframe></div>':'')+\n '<p class=\"subtle\" id=\"editor-information\"></p></section>'+\n '<section class=\"panel\"><details id=\"hosting-guide\"><summary>🌍 Predare site și opțiuni de găzduire</summary>'+\n '<p class=\"subtle\">Clientul își deține contul, domeniul și fotografiile. Furnizorul de hosting este plătit direct de client, dacă nu există un acord separat.</p>'+\n '<label class=\"field\"><span>De ce servicii are nevoie site-ul?</span><select id=\"hosting-mode\">'+\n '<option value=\"static\">Prezentare / galerie (fără funcții live)</option>'+\n '<option value=\"dynamic\">Rezervări, mesagerie, conturi sau administrare online</option>'+\n '</select></label><p class=\"subtle\" id=\"hosting-notice\"></p>'+\n '<div id=\"hosting-options\"></div><div class=\"row\" id=\"hosting-actions\"></div></details></section>'+\n (site?'<section class=\"panel\"><h2>Predare și colaborare</h2><div class=\"row\" id=\"handover-actions\"></div><div id=\"requests\"></div></section>':'');\n $('editor-top').append(button('← Site-urile mele',dashboard,'neutral'),button('Deconectare',signOut,'neutral'));\n populate('site-kind',kinds,draft.kind);populate('site-style',themes.map(t=>[t[0],t[1]]),draft.styleId);\n populate('site-lang',[['ro','Română'],['en','Engleză'],['both','Română + Engleză']],draft.lang);\n $('feat-contact').checked=draft.features?.contact===true;\n $('feat-booking').checked=draft.features?.booking===true;\n $('feat-shop').checked=draft.features?.shop===true;\n $('feat-auto-booking').checked=draft.commerce?.automaticConfirmation===true;\n $('feat-email-notices').checked=draft.commerce?.emailNotifications===true;\n populate('site-currency',[['GBP','GBP £'],['EUR','EUR €'],['RON','RON lei'],['USD','USD $']],draft.commerce?.currency||'GBP');\n populate('site-slot-minutes',[15,30,45,60,90,120,180,240].map(n=>[String(n),n+' minute']),String(draft.commerce?.slotMinutes||60));\n renderCatalog();\n populate('mgmt-mode',[['owner','Administrare proprie'],['managed','Mentenanță de către creator'],['shared','Administrare mixtă']],management.mode);\n populate('mgmt-currency',[['GBP','GBP'],['EUR','EUR'],['RON','RON']],management.currency||'GBP');\n populate('mgmt-hosting',[['owner','Proprietarul, separat'],['creator','Creatorul, prin ofertă separată']],management.hosting||'owner');\n populate('mgmt-backups',[['none','Nu sunt incluse'],['monthly','Lunar'],['weekly','Săptămânal']],management.backups||'none');\n $('mgmt-mode').onchange=modeFields;modeFields();\n if(!creating)$('mgmt-mode').disabled=true;\n $('contract-preview').onclick=()=>{\n  const m=creating?getManagement():management;\n  if(m.mode==='owner')return msg('Nu este necesar un contract de mentenanță plătită.');\n  const missing=['client','creator','monthly','edits','turnaround','extraCost','notice'].filter(k=>!m[k]);\n  if(missing.length)return msg('Completează tarifele și toate condițiile înainte de contract.');\n  const text=contractText(m,read('site-name'));\n  const dialog=$('dialog'),content=$('dialog-content');content.textContent=text;dialog.showModal();\n  $('dialog-download').onclick=()=>downloadText('proiect-mentenanta.txt',text);\n };\n renderPhotos();\n $('catalog-actions').append(button('＋ Adaugă produs',()=>{\n  if(products.length>=80)return msg('Catalogul are maximum 80 de produse.');\n  products.push({id:'p-'+crypto.randomUUID().replaceAll('-','').slice(0,12),title:'Produs nou',\n   description:'',priceMinor:0,inventory:0});dirty=true;renderCatalog();\n },'secondary'));\n $('hosting-mode').onchange=renderHostingOptions;\n renderHostingOptions();\n $('hosting-actions').append(button('💾 Descarcă ghidul pentru client',downloadHostingInstructions,'secondary'));\n fillNewPhotoTarget();\n for(const field of ['site-rooms','site-kind','site-description']){\n  $(field).addEventListener('change',()=>{renderPhotos();fillNewPhotoTarget()});\n }\n $('add-photo-input').onchange=async e=>{\n  try{await addPhoto(e.target.files?.[0])}catch(err){msg(err.message)}e.target.value='';\n };\n const photosRow=$('photo-actions');\n photosRow.append(button('＋ Adaugă fotografie',()=>$('add-photo-input').click()));\n const aiImage=button('✨ Imagine cu Eva (cote protejate)',async()=>{\n  const prompt=window.prompt('Descrie scena exactă pe care vrei să o genereze Eva:');\n  if(!prompt)return;\n  const composition=window.prompt('Compoziție: wide / full / medium / portrait','wide')||'wide';\n  aiImage.disabled=true;msg('Cererea este procesată numai dacă motorul AI a fost activat și contul este eligibil.');\n  try{\n   const result=await api('/api/ai/image','POST',{prompt,composition});\n   const encoded=String(result.image||'').split(',')[1]||'';\n   if(!/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)||encoded.length>7500000)throw Error('Datele imaginii sunt invalide.');\n   const binary=atob(encoded),buffer=new Uint8Array(binary.length);\n   for(let i=0;i<binary.length;i++)buffer[i]=binary.charCodeAt(i);\n   await addPhoto(new File([buffer],'eva-preview.jpg',{type:'image/jpeg'}));\n   msg('Imagine creată și introdusă în galerie. Verifică atent compoziția înainte de publicare.');\n  }catch(e){msg(e.message)}finally{aiImage.disabled=false}\n },'secondary');\n photosRow.append(aiImage);\n if(!editable){\n  for(const element of main.querySelectorAll('input,select,textarea')){\n   if(element.id==='mgmt-mode')continue;element.disabled=true;\n  }\n  photosRow.replaceChildren();\n  $('ai-copy-actions').textContent='Modul de mentenanță este activ. Solicită creatorului modificările necesare.';\n }\n if(!designEditable)for(const key of ['site-kind','site-style','site-lang'])$(key).disabled=true;\n if(!creating){\n  for(const el of main.querySelectorAll('input,textarea,select')){\n   el.addEventListener('input',()=>dirty=true);\n  }\n }\n const aiRow=$('ai-copy-actions');\n if(editable){\n  const generate=button('✨ Redactează + traduce automat cu Eva',async()=>{\n   const d=gather();\n   if(!d.name||d.description.length<15)return msg('Completează descrierea afacerii.');\n   generate.disabled=true;msg('Se solicită redactarea AI cu cont și cotă verificată.');\n   try{\n    const r=await api('/api/ai/site','POST',{name:d.name,kind:d.kind,style:d.styleId,\n     description:d.description,lang:d.lang});\n    for(const l of ['ro','en']){\n     if(r.copy?.[l])for(const key of ['headline','intro','about'])\n      setInput(l+'-'+key,r.copy[l][key]);\n     if(r.copy?.[l]?.services)setInput(l+'-services',lines(r.copy[l].services,'service'));\n    }\n    dirty=true;msg('Eva a pregătit textele. Revizuiește, apoi salvează și publică.');\n   }catch(e){msg(e.message)}finally{generate.disabled=false}\n  });\n  aiRow.append(generate);\n }\n const actions=$('editor-actions');\n if(editable){\n  const save=button(creating?'＋ Creează proiectul':'💾 Salvează modificările',async()=>{\n   save.disabled=true;\n   try{\n    const draft=gather();\n    if(creating){\n     const m=getManagement();\n     const r=await api('/api/sites','POST',{draft,management:m});\n     msg('Proiect creat. Îl poți previzualiza și publica doar după verificare.');\n     return openSite(r.id);\n    }\n    const r=await api('/api/sites/'+active.id,'PUT',{draft,version:active.version});\n    active.version=r.version;active.draft=draft;dirty=false;\n    msg('Modificările au fost salvate. Nu sunt încă publicate.');\n    $('preview').src='/api/sites/'+active.id+'/preview?t='+Date.now();\n   }catch(e){msg(e.message)}finally{save.disabled=false}\n  });\n  actions.append(save);\n }\n if(site){\n  $('visitor-inbox-actions').append(button('↻ Actualizează solicitările',refreshVisitorInbox,'secondary'));\n  $('visitor-inbox-actions').append(button('💾 Exportă inboxul',async()=>{\n   try{\n    const entries=await api('/api/sites/'+active.id+'/inbox');\n    downloadText('eva-inbox-'+active.id+'.json',JSON.stringify({\n     exportedAt:new Date().toISOString(),siteId:active.id,\n     notice:'Date personale ale vizitatorilor — păstrează fișierul în siguranță.',\n     items:entries.items||[]\n    },null,2));\n    msg('Inboxul a fost exportat. Fișierul conține date personale ale vizitatorilor.');\n   }catch(e){msg('Nu am putut exporta inboxul: '+e.message)}\n  },'secondary'));\n  refreshVisitorInbox();\n  const openPreview=button('👁 Previzualizează',()=>{\n   if(dirty)msg('Ai modificări nesalvate. Salvează pentru a le include în previzualizare.');\n   $('preview').src='/api/sites/'+active.id+'/preview?t='+Date.now();\n  },'secondary');\n  actions.append(openPreview);\n  if(editable)actions.append(button('🌐 Publică versiunea salvată',async()=>{\n   if(dirty)return msg('Salvează modificările înainte de publicare.');\n   try{const r=await api('/api/sites/'+active.id+'/publish','POST',{version:active.version});\n    active.publishedVersion=r.publishedVersion;\n    msg('Site publicat. Linkul poate fi trimis clientului.')}\n   catch(e){msg(e.message)}\n  }));\n  actions.append(button('💾 Proiect editabil / backup',()=>{\n   const body={schema:'mypocket-studio-project-v1',createdAt:new Date().toISOString(),\n    draft:active.draft,management:active.management};\n   downloadText('eva-site-'+active.id+'.pocket-site.json',JSON.stringify(body,null,2));\n   msg('Proiectul editabil a fost salvat local. Păstrează o copie de siguranță.');\n  },'secondary'));\n  actions.append(button('🔗 Copiază linkul site-ului',async()=>{\n   if(!active.publishedVersion)return msg('Publică mai întâi o versiune a site-ului.');\n   const url=location.origin+'/s/'+active.id;\n   try{await navigator.clipboard.writeText(url);msg('Linkul public al site-ului a fost copiat.')}\n   catch{window.prompt('Copiază linkul site-ului:',url)}\n  },'secondary'));\n  actions.append(button('💾 Exportă site HTML',()=>{\n   window.location.href='/api/sites/'+active.id+'/export';\n  },'secondary'));\n  const link=document.createElement('a');\n  link.href='/s/'+active.id;link.target='_blank';link.rel='noopener noreferrer';\n  link.textContent='Vezi site-ul publicat';actions.append(link);\n  $('editor-information').textContent='Versiunea curentă: '+active.version+\n   ' | Versiunea publicată: '+active.publishedVersion+' | Mod de administrare: '+management.mode+\n   ' | Rolul tău: '+role;\n  $('preview').src='/api/sites/'+active.id+'/preview';\n  const tools=$('handover-actions');\n  if(role==='owner'||(role==='creator'&&!site.ownerAssigned)){\n   tools.append(button('✉ Predă proprietarului',async()=>{\n    const email=window.prompt('E-mailul exact al proprietarului (pentru invitația unică):');\n    if(!email)return;\n    try{const result=await api('/api/sites/'+active.id+'/invite','POST',{email});\n     const link=location.origin+'/#invite='+result.invitation;\n     await navigator.clipboard.writeText(link);\n     msg('Invitația a fost copiată. Trimite linkul proprietarului printr-un canal privat. Expiră în 72 de ore.');\n    }catch(e){msg(e.message)}\n   }));\n   if(role==='owner'&&site.ownerAssigned)tools.append(button('Încheie mentenanța și retrage accesul creatorului',async()=>{\n    if(!confirm('Această acțiune retrage accesul creatorului. Confirmă numai după încheierea acordului de mentenanță.'))return;\n    try{await api('/api/sites/'+active.id+'/end-maintenance','POST',{});msg('Accesul creatorului a fost revocat.');openSite(active.id)}\n    catch(e){msg(e.message)}\n   },'neutral'));\n   if(management.mode!=='owner')tools.append(button('Solicită o modificare',async()=>{\n    const message=window.prompt('Descrie modificarea cerută:');\n    if(!message)return;\n    try{await api('/api/sites/'+active.id+'/request','POST',{message});msg('Solicitarea a fost transmisă.');openSite(active.id)}\n    catch(e){msg(e.message)}\n   },'secondary'));\n  }\n  if(active.requests?.length){\n   const r=$('requests'),title=document.createElement('h3');title.textContent='Solicitări de modificare';r.append(title);\n   active.requests.forEach(item=>{\n    const p=document.createElement('p');p.className='notice';p.textContent=item.message+' · '+item.status;r.append(p);\n    if(role==='creator'&&item.status==='open')r.append(button('Marchează rezolvat',async()=>{\n     await api('/api/sites/'+active.id+'/complete-request','POST',{requestId:item.id});openSite(active.id)\n    },'secondary'));\n   });\n  }\n }\n}\nasync function boot(){\n offerInviteFromHash();\n try{const r=await api('/api/session');user=r.user;setHeader();\n  await acceptInvitation();await dashboard()}\n catch{renderAuth(inviteHash?'register':'login')}\n}\n$('dialog-close').onclick=()=>$('dialog').close();\nboot();\n})();\n</script></body></html>";
